sp_widget.client_script:
api.controller = function ($scope,spUtil,$window,nowAttachmentHandler) {

    var c = this;

    c.submitting = false;
    c.uploading = false;

    c.form = {
        courseEffectiveness: "",
        deliveryMethods: "",
        trainerEffectiveness: "",
        overallRating: 0,
        wentWell: "",
        improvement: "",
        otherComments: "",
        recommendCourse: ""
    };

    /*
     * Attachments are uploaded directly to the Learning Request.
     */
    $scope.attachmentHandler =
        new nowAttachmentHandler();

    if (
        c.data &&
        c.data.table &&
        c.data.sys_id
    ) {
        $scope.attachmentHandler.setParams(
            c.data.table,
            c.data.sys_id,
            1024 *
            1024 *
            (c.data.maxAttachmentSize || 10)
        );
    }

    /*
     * Track attachment upload state.
     */
    var uploadStartListener =
        $scope.$on(
            "sp.attachments.upload.start",
            function () {
                c.uploading = true;
            }
        );

    var attachmentUpdateListener =
        $scope.$on(
            "sp.attachments.update",
            function () {
                c.uploading = false;
            }
        );

    var uploadCompleteListener =
        $scope.$on(
            "sp.attachments.upload.complete",
            function () {
                c.uploading = false;
            }
        );

    $scope.$on(
        "$destroy",
        function () {
            uploadStartListener();
            attachmentUpdateListener();
            uploadCompleteListener();
        }
    );

    c.calculateOverallRating =
        function () {

            var course =
                parseInt(
                    c.form.courseEffectiveness,
                    10
                );

            var delivery =
                parseInt(
                    c.form.deliveryMethods,
                    10
                );

            var trainer =
                parseInt(
                    c.form.trainerEffectiveness,
                    10
                );

            if (
                isNaN(course) ||
                isNaN(delivery) ||
                isNaN(trainer)
            ) {
                c.form.overallRating = 0;
                return;
            }

            c.form.overallRating =
                Math.round(
                    (
                        (
                            course +
                            delivery +
                            trainer
                        ) /
                        3
                    ) *
                    10
                ) / 10;
        };

    c.clearForm =
        function () {

            if (
                c.submitting ||
                c.uploading
            ) {
                return;
            }

            c.form.courseEffectiveness = "";
            c.form.deliveryMethods = "";
            c.form.trainerEffectiveness = "";
            c.form.overallRating = 0;
            c.form.wentWell = "";
            c.form.improvement = "";
            c.form.otherComments = "";
            c.form.recommendCourse = "";
        };

    c.cancel =
        function () {

            if (
                c.submitting ||
                c.uploading
            ) {
                return;
            }

            $window.location.href =
                "?id=check_my_records_asean";
        };

    c.submitFeedback =
        function () {

            if (c.uploading) {
                spUtil.addErrorMessage(
                    "Please wait until the attachment upload is completed."
                );
                return;
            }

            if (
                !c.data ||
                !c.data.sys_id
            ) {
                spUtil.addErrorMessage(
                    "Learning application sys_id is missing."
                );
                return;
            }

            if (
                !c.form.courseEffectiveness
            ) {
                spUtil.addErrorMessage(
                    "Please select Course Effectiveness."
                );
                return;
            }

            if (
                !c.form.deliveryMethods
            ) {
                spUtil.addErrorMessage(
                    "Please select Course Delivery Methods."
                );
                return;
            }

            if (
                !c.form.trainerEffectiveness
            ) {
                spUtil.addErrorMessage(
                    "Please select Trainer Effectiveness."
                );
                return;
            }

            if (
                !c.form.recommendCourse
            ) {
                spUtil.addErrorMessage(
                    "Please select whether you recommend this course."
                );
                return;
            }

            c.submitting = true;

            c.server.get({

                action:
                    "submitFeedback",

                sys_id:
                    c.data.sys_id,

                course_effectiveness:
                    c.form.courseEffectiveness,

                delivery_methods:
                    c.form.deliveryMethods,

                trainer_effectiveness:
                    c.form.trainerEffectiveness,

                overall_rating:
                    c.form.overallRating,

                went_well:
                    c.form.wentWell,

                improvement:
                    c.form.improvement,

                other_comments:
                    c.form.otherComments,

                recommend_course:
                    c.form.recommendCourse

            }).then(

                function (response) {

                    c.submitting = false;

                    if (
                        response.data &&
                        response.data.success
                    ) {
                        spUtil.addInfoMessage(
                            response.data.message ||
                            "Feedback submitted successfully."
                        );

                        $window.setTimeout(
                            function () {
                                $window.location.href =
                                    "?id=check_my_records_asean";
                            },
                            800
                        );

                    } else {
                        spUtil.addErrorMessage(
                            response.data.message ||
                            "Unable to submit feedback."
                        );
                    }
                },

                function () {

                    c.submitting = false;

                    spUtil.addErrorMessage(
                        "An error occurred while submitting feedback."
                    );
                }
            );
        };
};

sp_widget.css:
.learning-feedback-wrapper {
    width: 100%;
    max-width: 1180px;
    margin: 25px auto;
    background: #ffffff;
    border: 1px solid #bcbcbc;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
}

.learning-feedback-wrapper * {
    box-sizing: border-box;
}

.feedback-header {
    position: relative;
    min-height: 88px;
    padding: 22px 28px;
    border-bottom: 1px solid #eeeeee;
}

.feedback-title {
    margin: 0;
    color: #ed5a13;
    font-size: 30px;
    font-weight: 600;
    line-height: 42px;
}

.header-details {
    position: absolute;
    top: 17px;
    right: 30px;
    min-width: 350px;
    font-size: 14px;
}

.header-detail-row {
    display: flex;
    align-items: center;
    margin-bottom: 9px;
}

.header-label {
    display: inline-block;
    width: 120px;
    color: #555555;
    font-size: 12px;
    text-decoration: underline;
}

.header-value {
    color: #333333;
    word-break: break-word;
}

.feedback-content {
    display: flex;
    width: 100%;
    padding: 22px 24px;
}

.feedback-left-section {
    width: 42%;
    padding-right: 25px;
}

.feedback-right-section {
    width: 58%;
    padding-left: 25px;
    border-left: 1px solid #e5e5e5;
}

.feedback-info-row {
    display: flex;
    width: 100%;
    margin-bottom: 21px;
}

.feedback-info-column {
    width: 50%;
    padding-right: 15px;
}

.feedback-info-column:last-child {
    padding-right: 0;
    padding-left: 15px;
}

.feedback-info-block {
    margin-bottom: 21px;
}

.feedback-label {
    display: block;
    margin-bottom: 7px;
    color: #444444;
    font-size: 14px;
    font-weight: 600;
}

.feedback-value {
    min-height: 22px;
    color: #666666;
    font-size: 14px;
    line-height: 21px;
    word-break: break-word;
}

/* Attachment section */
.feedback-attachment-box {
    position: relative;
    width: 100%;
    min-height: 180px;
    margin-top: 26px;
    padding: 16px 18px;
    overflow: visible;
    background: #ffffff;
    border: 1px solid #cccccc;
}

.attachment-title {
    margin-bottom: 10px;
    color: #333333;
    font-size: 15px;
    font-weight: 600;
}

.attachment-help {
    margin-bottom: 14px;
    color: #888888;
    font-size: 13px;
    line-height: 20px;
}

/* Custom paperclip attachment button */
.custom-attachment-control {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 105px;
    height: 42px;
    padding: 0 12px;
    background: #ffffff;
    border: 2px solid #222222;
    border-radius: 3px;
    cursor: pointer;
}

.custom-attachment-control:hover {
    background: #f5f5f5;
}

.custom-attachment-control:focus-within {
    outline: 2px solid #0070d2;
    outline-offset: 2px;
}

/*
 * Keep the actual ServiceNow attachment button over the
 * custom icon and text, but make its default UI invisible.
 */
.custom-attachment-control sp-attachment-button {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 5;
    display: block;
    width: 100%;
    height: 100%;
    opacity: 0;
    cursor: pointer;
}

.custom-attachment-control sp-attachment-button .btn,
.custom-attachment-control sp-attachment-button button {
    width: 100% !important;
    height: 100% !important;
    margin: 0 !important;
    padding: 0 !important;
    cursor: pointer;
}

.custom-attachment-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-right: 7px;
    color: #333333;
    font-size: 17px;
    pointer-events: none;
}

.custom-attachment-text {
    color: #333333;
    font-size: 14px;
    font-weight: 500;
    white-space: nowrap;
    pointer-events: none;
}

.attachment-picker-list {
    width: 100%;
    margin-top: 12px;
}

.attachment-picker-list sp-attachment-picker {
    display: block;
    width: 100%;
}

.attachment-picker-list .attachment {
    display: flex;
    align-items: center;
    width: 100%;
    margin-top: 7px;
    padding: 8px 10px;
    background: #f7f7f7;
    border: 1px solid #dddddd;
}

.attachment-picker-list .attachment-name {
    max-width: calc(100% - 55px);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.attachment-upload-status {
    margin-top: 12px;
    color: #555555;
    font-size: 13px;
}

.rating-instruction {
    margin-bottom: 17px;
    color: #333333;
    font-size: 14px;
    font-weight: 600;
    line-height: 21px;
}

.rating-grid {
    display: flex;
    width: 100%;
    margin-bottom: 22px;
}

.rating-column {
    width: 25%;
    padding-right: 10px;
}

.rating-column:last-child {
    padding-right: 0;
}

.rating-label {
    display: block;
    min-height: 44px;
    margin-bottom: 7px;
    color: #444444;
    font-size: 13px;
    font-weight: 600;
    line-height: 18px;
}

.rating-column .form-control {
    width: 100%;
    height: 34px;
}

.mandatory {
    margin-right: 2px;
    color: #d9534f;
}

.overall-rating {
    width: 100%;
    height: 34px;
    padding: 6px 10px;
    background: #ed6a05;
    color: #ffffff;
    font-size: 18px;
    font-weight: 600;
    line-height: 22px;
    text-align: center;
}

.feedback-form-group {
    width: 100%;
    margin-bottom: 17px;
}

.feedback-textarea {
    width: 100%;
    min-height: 76px;
    resize: vertical;
}

.recommendation-group {
    width: 260px;
    margin-top: 5px;
}

.recommendation-group .form-control {
    width: 100%;
}

.feedback-actions {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    min-height: 75px;
    padding: 14px 20px 5px;
}

.feedback-text-button {
    min-width: 110px;
    margin: 0 42px;
    padding: 9px 15px;
    background: transparent;
    border: 0;
    font-size: 14px;
    font-weight: 600;
    text-align: center;
}

.clear-button {
    color: #aaa31a;
}

.cancel-button {
    color: #e54337;
}

.feedback-submit-button {
    min-width: 130px;
    margin: 0 42px;
    padding: 10px 23px;
    background: #29b64a;
    border: 1px solid #17983a;
    border-radius: 0;
    color: #ffffff;
    font-size: 14px;
    font-weight: 600;
}

.feedback-submit-button:hover,
.feedback-submit-button:focus,
.feedback-submit-button:active {
    background: #179b39;
    color: #ffffff;
}

.feedback-submit-button[disabled],
.feedback-text-button[disabled] {
    cursor: not-allowed;
    opacity: 0.65;
}

.feedback-back-section {
    width: 100%;
    padding: 8px 20px 25px;
    text-align: center;
}

.feedback-back-button {
    display: inline-flex;
    align-items: center;
    min-width: 105px;
    padding: 5px 18px 5px 5px;
    background: #ffffff;
    border: 1px solid #cccccc;
    border-radius: 25px;
    color: #333333 !important;
    font-weight: 600;
    text-decoration: none !important;
}

.feedback-back-button:hover,
.feedback-back-button:focus {
    background: #f5f5f5;
    color: #333333 !important;
    text-decoration: none !important;
}

.feedback-back-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 33px;
    height: 33px;
    margin-right: 9px;
    background: #0070d2;
    border-radius: 50%;
    color: #ffffff;
}

@media (max-width: 991px) {

    .feedback-content {
        display: block;
    }

    .feedback-left-section,
    .feedback-right-section {
        width: 100%;
        padding: 0;
    }

    .feedback-right-section {
        margin-top: 25px;
        padding-top: 25px;
        border-top: 1px solid #e5e5e5;
        border-left: 0;
    }

    .header-details {
        position: static;
        margin-top: 12px;
    }

    .feedback-header {
        min-height: auto;
    }
}

@media (max-width: 767px) {

    .learning-feedback-wrapper {
        margin: 10px auto;
    }

    .feedback-header {
        padding: 18px;
    }

    .feedback-title {
        font-size: 24px;
        line-height: 32px;
    }

    .feedback-content {
        padding: 18px;
    }

    .feedback-info-row,
    .rating-grid {
        display: block;
    }

    .feedback-info-column,
    .rating-column {
        width: 100%;
        margin-bottom: 16px;
        padding: 0;
    }

    .feedback-info-column:last-child {
        padding: 0;
    }

    .rating-label {
        min-height: auto;
    }

    .recommendation-group {
        width: 100%;
    }

    .feedback-actions {
        flex-direction: column;
    }

    .feedback-text-button,
    .feedback-submit-button {
        width: 160px;
        margin: 6px 0;
    }

    .header-detail-row {
        display: block;
    }

    .header-label {
        display: block;
        width: auto;
        margin-bottom: 3px;
    }
}

sp_widget.script:
(function () {

    var TABLE_NAME =
        "x_1549902_asean_0_learning_application";

    var APPROVED =
        "approved";

    var COMPLETED =
        "completed";

    data.table = TABLE_NAME;
    data.maxAttachmentSize = 10;
    data.sys_id = "";
    data.errorMessage = "";
    data.employeeName = "";
    data.employeeEmail = "";
    data.country = "";
    data.courseTitle = "";
    data.requestNumber = "";
    data.ticketStatus = "";
    data.statusValue = "";

    if (
        input &&
        input.action === "submitFeedback"
    ) {
        submitFeedback();
        return;
    }

    loadLearningApplication();

    function loadLearningApplication() {

        var sysId =
            $sp.getParameter("sys_id");

        if (!sysId) {
            data.errorMessage =
                "Learning application sys_id is missing.";
            return;
        }

        var applicationGR =
            new GlideRecord(TABLE_NAME);

        if (!applicationGR.get(sysId)) {
            data.errorMessage =
                "Learning application record was not found.";
            return;
        }

        var currentStatus =
            applicationGR.getValue("u_status") || "";

        /*
         * Feedback is available only when the request is Approved.
         */
        if (currentStatus !== APPROVED) {
            data.errorMessage =
                "Feedback can only be submitted when the application status is Approved.";
            return;
        }

        /*
         * Allow the employee linked to the request.
         * Admin is allowed for testing.
         */
        var employeeSysId =
            applicationGR.getValue(
                "u_employee_name"
            ) || "";

        if (
            employeeSysId &&
            employeeSysId !== gs.getUserID() &&
            !gs.hasRole("admin")
        ) {
            data.errorMessage =
                "You are not authorized to submit feedback for this learning application.";
            return;
        }

        data.sys_id =
            applicationGR.getUniqueValue();

        data.requestNumber =
            applicationGR.getValue("number") || "";

        data.employeeName =
            applicationGR.getDisplayValue(
                "u_employee_name"
            ) || "";

        data.employeeEmail =
            applicationGR.getValue(
                "u_employee_email"
            ) || "";

        data.country =
            applicationGR.getDisplayValue(
                "u_country"
            ) || "";

        data.courseTitle =
            applicationGR.getValue(
                "u_course_title"
            ) || "";

        data.ticketStatus =
            applicationGR.getDisplayValue(
                "u_status"
            ) || "";

        data.statusValue =
            currentStatus;
    }

    function submitFeedback() {

        data.success = false;
        data.message = "";

        if (!input.sys_id) {
            data.message =
                "Learning application sys_id is missing.";
            return;
        }

        if (
            !isValidRating(
                input.course_effectiveness
            )
        ) {
            data.message =
                "Course Effectiveness rating is mandatory.";
            return;
        }

        if (
            !isValidRating(
                input.delivery_methods
            )
        ) {
            data.message =
                "Course Delivery Methods rating is mandatory.";
            return;
        }

        if (
            !isValidRating(
                input.trainer_effectiveness
            )
        ) {
            data.message =
                "Trainer Effectiveness rating is mandatory.";
            return;
        }

        if (
            input.recommend_course !== "yes" &&
            input.recommend_course !== "no"
        ) {
            data.message =
                "Please select whether you recommend this course.";
            return;
        }

        var applicationGR =
            new GlideRecord(TABLE_NAME);

        if (!applicationGR.get(input.sys_id)) {
            data.message =
                "Learning application record was not found.";
            return;
        }

        var currentStatus =
            applicationGR.getValue("u_status") || "";

        /*
         * Confirm that the request is still Approved.
         */
        if (currentStatus !== APPROVED) {
            data.message =
                "Feedback can only be submitted when the status is Approved.";
            return;
        }

        /*
         * Confirm employee authorization.
         */
        var employeeSysId =
            applicationGR.getValue(
                "u_employee_name"
            ) || "";

        if (
            employeeSysId &&
            employeeSysId !== gs.getUserID() &&
            !gs.hasRole("admin")
        ) {
            data.message =
                "You are not authorized to submit feedback for this learning application.";
            return;
        }

        /*
         * Confirm that the Comments journal field exists.
         */
        if (
            !applicationGR.isValidField(
                "comments"
            )
        ) {
            data.message =
                "The Comments field is not available on the Learning Application table.";
            return;
        }

        /*
         * Confirm write permission.
         */
        if (!applicationGR.canWrite()) {
            data.message =
                "You do not have permission to update this learning application.";
            return;
        }

        var overallRating =
            calculateAverage(
                input.course_effectiveness,
                input.delivery_methods,
                input.trainer_effectiveness
            );

        var attachmentCount =
            getAttachmentCount(
                TABLE_NAME,
                applicationGR.getUniqueValue()
            );

        var feedbackLines = [];

        feedbackLines.push(
            "LEARNING FEEDBACK SUBMITTED"
        );

        feedbackLines.push("");

        feedbackLines.push(
            "Request Number: " +
            (
                applicationGR.getValue("number") ||
                "N/A"
            )
        );

        feedbackLines.push(
            "Course Title: " +
            (
                applicationGR.getValue(
                    "u_course_title"
                ) ||
                "N/A"
            )
        );

        feedbackLines.push(
            "Employee Name: " +
            (
                applicationGR.getDisplayValue(
                    "u_employee_name"
                ) ||
                "N/A"
            )
        );

        feedbackLines.push(
            "Employee Email: " +
            (
                applicationGR.getValue(
                    "u_employee_email"
                ) ||
                "N/A"
            )
        );

        feedbackLines.push(
            "Submitted By: " +
            gs.getUserDisplayName()
        );

        feedbackLines.push(
            "Submitted On: " +
            new GlideDateTime().getDisplayValue()
        );

        feedbackLines.push("");

        feedbackLines.push(
            "RATINGS"
        );

        feedbackLines.push(
            "------------------------------"
        );

        feedbackLines.push(
            "Course Effectiveness: " +
            input.course_effectiveness +
            "/5"
        );

        feedbackLines.push(
            "Course Delivery Methods: " +
            input.delivery_methods +
            "/5"
        );

        feedbackLines.push(
            "Trainer's Effectiveness: " +
            input.trainer_effectiveness +
            "/5"
        );

        feedbackLines.push(
            "Overall Course Rating: " +
            overallRating +
            "/5"
        );

        feedbackLines.push("");

        feedbackLines.push(
            "What went well:"
        );

        feedbackLines.push(
            cleanText(
                input.went_well
            ) ||
            "No comments provided"
        );

        feedbackLines.push("");

        feedbackLines.push(
            "What can be improved:"
        );

        feedbackLines.push(
            cleanText(
                input.improvement
            ) ||
            "No comments provided"
        );

        feedbackLines.push("");

        feedbackLines.push(
            "Any other comment:"
        );

        feedbackLines.push(
            cleanText(
                input.other_comments
            ) ||
            "No comments provided"
        );

        feedbackLines.push("");

        feedbackLines.push(
            "Will recommend this course: " +
            (
                input.recommend_course === "yes"
                    ? "Yes"
                    : "No"
            )
        );

        feedbackLines.push("");

        feedbackLines.push(
            "Attachments uploaded: " +
            attachmentCount
        );

        var consolidatedFeedback =
            feedbackLines.join("\n");

        /*
         * Save consolidated feedback only in the Comments
         * journal field.
         *
         * Nothing is written to:
         * - work_notes
         * - u_comment
         */
        applicationGR.comments =
            consolidatedFeedback;

        /*
         * Move the request from Approved to Completed.
         */
        applicationGR.setValue(
            "u_status",
            COMPLETED
        );

        try {

            var updatedSysId =
                applicationGR.update();

            if (!updatedSysId) {
                data.message =
                    "The Learning Request could not be updated. Check Business Rules and ACLs.";
                return;
            }

            /*
             * Verify that the Comments journal entry was created.
             */
            var commentsCreated =
                verifyCommentsEntry(
                    applicationGR.getUniqueValue()
                );

            if (!commentsCreated) {
                gs.warn(
                    "Feedback was submitted and the request was completed, " +
                    "but a Comments journal entry was not found for record " +
                    applicationGR.getUniqueValue()
                );
            }

            var finalAttachmentCount =
                getAttachmentCount(
                    TABLE_NAME,
                    applicationGR.getUniqueValue()
                );

            data.success = true;

            data.message =
                "Feedback submitted successfully. " +
                "The Learning Request has been moved to Completed. " +
                "Feedback has been added to Comments. " +
                finalAttachmentCount +
                " attachment(s) are available on the Learning Request.";

        } catch (error) {

            gs.error(
                "ASEAN feedback submission failed for record " +
                applicationGR.getUniqueValue() +
                ". Error: " +
                error
            );

            data.message =
                "Unable to submit feedback: " +
                error;
        }
    }

    function isValidRating(value) {

        var rating =
            parseInt(value, 10);

        return (
            !isNaN(rating) &&
            rating >= 1 &&
            rating <= 5
        );
    }

    function calculateAverage(
        courseRating,
        deliveryRating,
        trainerRating
    ) {

        var total =
            parseInt(courseRating, 10) +
            parseInt(deliveryRating, 10) +
            parseInt(trainerRating, 10);

        return Math.round(
            (total / 3) * 10
        ) / 10;
    }

    function cleanText(value) {

        if (
            value === null ||
            value === undefined
        ) {
            return "";
        }

        return String(value).trim();
    }

    function getAttachmentCount(
        tableName,
        recordSysId
    ) {

        var count = 0;

        var attachmentGR =
            new GlideRecord(
                "sys_attachment"
            );

        attachmentGR.addQuery(
            "table_name",
            tableName
        );

        attachmentGR.addQuery(
            "table_sys_id",
            recordSysId
        );

        attachmentGR.query();

        while (attachmentGR.next()) {
            count++;
        }

        return count;
    }

    function verifyCommentsEntry(
        recordSysId
    ) {

        var journalGR =
            new GlideRecord(
                "sys_journal_field"
            );

        journalGR.addQuery(
            "name",
            TABLE_NAME
        );

        journalGR.addQuery(
            "element_id",
            recordSysId
        );

        journalGR.addQuery(
            "element",
            "comments"
        );

        journalGR.orderByDesc(
            "sys_created_on"
        );

        journalGR.setLimit(1);
        journalGR.query();

        return journalGR.hasNext();
    }

})();
